<script setup lang="ts">
import { computed,reactive,ref,watch } from 'vue';
import { Download,PackageCheck,Upload,FolderOpen,ExternalLink,Cloud,Archive,Check,FileArchive } from '@lucide/vue';
import { desk,safely,request,operation,apiPath,downloadDeployment,binary,loadProject,notify,openBrowse } from './store';
import { bytes,when,newestReleases,type Data } from './model';
const releases=computed(()=>newestReleases(desk.project?.releases));
const release=ref(''),platform=ref('windows-x64'),packageInput=ref<HTMLInputElement|null>(null),packageFile=ref<File|null>(null),plan=ref<Data|null>(null),agent=ref('0.1.2');
const program=reactive({sourceDirectory:'',version:'',launchPath:'DreamingFishUpdater.exe'});
const destination=ref(''),instance=ref('');const method=ref('export');
const hosting=reactive({outputDirectory:'',baseUrl:'',username:'',password:'',endpoint:'',region:'auto',bucket:'',prefix:'',accessKeyId:'',secretAccessKey:'',sessionToken:'',addressingStyle:'PATH',exportFirst:true});
const result=ref<Data|null>(null);
const programs=ref<Data[]>([]),currentProgram=ref('');
let platformRequest=0;
watch(()=>[desk.project,platform.value],()=>{const generation=++platformRequest;programs.value=[];currentProgram.value='';safely(async()=>{const details=await request(apiPath(`?platform=${encodeURIComponent(platform.value)}`));if(generation===platformRequest){programs.value=[...(details.playerPrograms||[])].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));currentProgram.value=details.currentProgramVersion||'';}});},{immediate:true});
watch(()=>desk.browseValues['deployment-output'],value=>{if(value)destination.value=value;});
watch(()=>desk.projectId,()=>{release.value='';plan.value=null;packageFile.value=null;result.value=null;});
async function checkPackage(){if(!packageFile.value)return;await operation(async()=>{plan.value=await binary(apiPath(`/program-package?fileName=${encodeURIComponent(packageFile.value!.name)}`),packageFile.value!);},'正在上传并识别玩家端…');}
async function publishPackage(){await operation(async()=>{await request(apiPath('/program-package'),'POST',{id:plan.value?.id,minimumBootstrapVersion:agent.value});plan.value=null;packageFile.value=null;await loadProject();notify('玩家端程序已发布');},'正在发布玩家端…');}
async function publishDirectory(){await operation(async()=>{await request(apiPath('/programs'),'POST',{...program,platform:platform.value,minimumBootstrapVersion:agent.value});await loadProject();notify('玩家端程序已发布');});}
async function writeDeployment(){await operation(async()=>{result.value=await request(apiPath('/deployment'),'POST',{platform:platform.value,releaseId:release.value||releases.value[0]?.releaseId,outputDirectory:destination.value});notify('部署包已生成');},'正在写入部署包…');}
async function prepareInstance(){await operation(async()=>{result.value=await request(apiPath('/instance'),'POST',{platform:platform.value,releaseId:release.value||releases.value[0]?.releaseId,instanceDirectory:instance.value});notify('玩家实例已准备');},'正在准备实例…');}
async function distribute(){await operation(async()=>{result.value=await request(apiPath(method.value==='export'?'/distribution-export':method.value==='webdav'?'/distribution-webdav':'/distribution-s3'),'POST',hosting);hosting.password='';hosting.secretAccessKey='';hosting.sessionToken='';notify('静态分发内容已处理完成');},'正在准备分发…');}
</script>
<template>
 <section v-if="desk.section==='deployment'" class="delivery-workspace"><div class="delivery-main"><span class="overline">首次发放</span><h2>把整合包交给玩家</h2><p class="intro-copy">选择已经发布的版本，生成包含更新器与启动说明的部署包。</p><div class="delivery-preview"><div class="package-illustration"><FileArchive :size="48"/></div><div><strong>{{desk.project?.displayName}}</strong><p>当前玩家端 {{currentProgram||'尚未发布'}}</p><small>{{desk.project?.publicBaseUrl}}</small></div></div>
   <div class="delivery-fields"><label>整合包版本<select v-model="release"><option value="">最新发布 {{releases[0]?.displayVersion||''}}</option><option v-for="r in releases" :key="r.releaseId" :value="r.releaseId">{{r.displayVersion}} · #{{r.sequence}}</option></select></label><label>玩家平台<select v-model="platform"><option value="windows-x64">Windows x64</option><option value="linux-x64">Linux x64</option></select></label></div><button class="accent delivery-download" :disabled="desk.busy||!releases.length||!currentProgram" @click="safely(()=>downloadDeployment(release||releases[0]?.releaseId,platform))"><Download :size="18"/>生成并下载部署 ZIP</button>
   <p class="field-help">生成后，按包内说明接入玩家的 PCL、HMCL 或其他启动器。</p>
   <details class="advanced"><summary>写入管理端目录 / 准备现有实例</summary><label>部署包输出目录<div class="field-with-button"><input v-model="destination" placeholder="管理端所在电脑或服务器的目录"><button @click="openBrowse('directory','deployment-output',destination)"><FolderOpen :size="16"/></button></div></label><button :disabled="!destination||desk.busy" @click="safely(writeDeployment)">写入部署包</button><label>现有实例目录<input v-model="instance" placeholder="包含 mods、config 的玩家实例目录"></label><button :disabled="!instance||desk.busy" @click="safely(prepareInstance)">准备此实例</button></details><p v-if="result" class="success-copy">{{result.outputDirectory||result.instanceDirectory||'处理完成'}}</p>
  </div><aside class="delivery-guide"><h3>发放流程</h3><ol><li><strong>发布整合包</strong><p>确认文件和维护设置已经发布。</p></li><li><strong>发布玩家端程序</strong><p>选择用于这个项目的更新器版本。</p></li><li><strong>制作部署包</strong><p>下载 ZIP，接入启动器并完成一次启动测试。</p></li></ol><button @click="desk.section='programs'">管理玩家端程序 <ExternalLink :size="14"/></button></aside></section>
 <section v-else-if="desk.section==='programs'" class="program-workspace"><header class="view-toolbar"><div><strong>玩家端程序</strong><span>上传发行包，确认后签名发布</span></div><select v-model="platform" aria-label="程序平台" style="width:140px"><option value="windows-x64">Windows x64</option><option value="linux-x64">Linux x64</option></select><span class="current-tag">当前 {{currentProgram||'未发布'}}</span></header><div class="program-content"><div class="program-upload" @dragover.prevent @drop.prevent="packageFile=$event.dataTransfer?.files[0]||null;plan=null"><FileArchive :size="34"/><strong>{{packageFile?.name||'选择玩家端发行 ZIP'}}</strong><p>{{packageFile?bytes(packageFile.size):'保留原发行包结构，系统会识别平台和版本。'}}</p><div><button @click="packageInput?.click()">选择 ZIP</button><button :disabled="!packageFile||desk.busy" @click="safely(checkPackage)">检查发行包</button></div><input ref="packageInput" type="file" accept=".zip" hidden @change="packageFile=($event.target as HTMLInputElement).files?.[0]||null;plan=null"></div>
  <div v-if="plan" class="program-plan"><PackageCheck :size="24"/><div><strong>已识别 {{plan.version}} · {{plan.platform}}</strong><p>{{plan.problem||plan.launcher||plan.sourceRelative||''}}</p></div><button class="accent" :disabled="desk.busy||!plan.publishable" @click="safely(publishPackage)">确认发布</button></div><table class="simple-table"><thead><tr><th>版本</th><th>平台</th><th>发布时间</th></tr></thead><tbody><tr v-for="p in programs" :key="p.manifestSha256"><td>{{p.version}}</td><td>{{p.platform}}</td><td>{{when(p.createdAt)}}</td></tr></tbody></table>
  <details class="advanced"><summary>从已有程序目录发布</summary><div class="form-grid"><label>程序目录<input v-model="program.sourceDirectory"></label><label>程序版本<input v-model="program.version"></label><label>启动文件<input v-model="program.launchPath"></label><label>最低 Agent 版本<input v-model="agent"></label></div><button :disabled="!program.sourceDirectory||desk.busy" @click="safely(publishDirectory)">发布目录中的程序</button></details></div></section>
 <section v-else class="hosting-workspace"><header class="view-toolbar"><div><strong>外部托管</strong><span>让 HTTP、WebDAV 或对象存储提供玩家下载</span></div></header><div class="hosting-content"><div class="segmented"><button v-for="item in [{id:'export',title:'仅导出'},{id:'webdav',title:'WebDAV'},{id:'s3',title:'对象存储'}]" :key="item.id" :class="{active:method===item.id}" @click="method=item.id">{{item.title}}</button></div><form @submit.prevent="safely(distribute)"><label>静态目录<input v-model="hosting.outputDirectory" placeholder="管理端生成静态文件的目录" required></label><template v-if="method==='webdav'"><label>WebDAV / HTTP PUT 地址<input v-model="hosting.baseUrl" type="url" required></label><div class="form-grid"><label>用户名<input v-model="hosting.username" autocomplete="off"></label><label>密码<input v-model="hosting.password" type="password" autocomplete="off"></label></div></template>
  <template v-if="method==='s3'"><label>S3 Endpoint<input v-model="hosting.endpoint" type="url" required></label><div class="form-grid"><label>Region<input v-model="hosting.region" required></label><label>Bucket<input v-model="hosting.bucket" required></label><label>目录前缀<input v-model="hosting.prefix"></label><label>寻址方式<select v-model="hosting.addressingStyle"><option value="PATH">Path</option><option value="VIRTUAL_HOST">Virtual hosted</option></select></label><label>Access Key ID<input v-model="hosting.accessKeyId" autocomplete="off" required></label><label>Secret Access Key<input v-model="hosting.secretAccessKey" type="password" autocomplete="off" required></label></div><details class="advanced"><summary>临时会话令牌</summary><input v-model="hosting.sessionToken" type="password" autocomplete="off"></details></template><button class="accent" :disabled="desk.busy"><Cloud :size="16"/>{{method==='export'?'导出静态内容':'导出并上传'}}</button></form><div v-if="result" class="hosting-result"><Check :size="20"/><div><strong>处理完成</strong><p>{{result.outputDirectory||result.destination}}</p><small>{{result.objectCount||result.fileCount||result.completedFileCount||''}} 项 · {{bytes(result.totalObjectBytes||result.totalBytes||0)}}</small></div></div></div></section>
</template>
